function Episodes(){const{data,loading,error}=useEpisodes();const[q,setQ]=useState("");const[s,setS]=useState("all");const[t,setT]=useState("all");const seasons=useMemo(()=>Array.from(new Set(data.map(e=>e.season).filter(Boolean))).sort((a,b)=>a-b),[data]);const items=useMemo(()=>data.filter(e=>(s==="all"||String(e.season)===s)&&(t==="all"||(e.content_type||"main")===t)&&(!q||(e.title+" "+(e.description||"")).toLowerCase().includes(q.toLowerCase()))),[data,q,s,t]);return <Shell><main className="page"><div className="page-head"><div className="eyebrow">EPISODES</div><h1>The archive.</h1><p>Main episodes, bonus drops and special behind-the-scenes entries — kept together, clearly.</p></div><div className="filters"><label className="field"><Search size={17}/><input placeholder="Search episodes…" value={q} onChange={e=>setQ(e.target.value)}/></label><label className="select">Season<select value={s} onChange={e=>setS(e.target.value)}><option value="all">All seasons</option>{seasons.map(x=><option key={x} value={x}>Season {x}</option>)}</select></label></div><div className="type-tabs" role="tablist" aria-label="Entry type"><button className={t==="all"?"active":""} onClick={()=>setT("all")}>All</button><button className={t==="main"?"active":""} onClick={()=>setT("main")}>Main</button><button className={t==="bonus"?"active":""} onClick={()=>setT("bonus")}>Bonus</button><button className={t==="special"?"active":""} onClick={()=>setT("special")}>Special</button></div>{error&&<div className="error">{error}</div>}{loading?<Loading count={6}/>:<><div className="count">{items.length} {items.length===1?"entry":"entries"}</div><Grid items={items}/><HighRevenueBannerAd/></>}</main></Shell>}

function SearchPage(){const params=new URLSearchParams(location.search);const[q,setQ]=useState(params.get("q")||"");const{data,loading}=useEpisodes();const items=useMemo(()=>data.filter(e=>(e.title+" "+(e.description||"")).toLowerCase().includes(q.trim().toLowerCase())),[data,q]);return <Shell><main className="page"><div className="page-head"><div className="eyebrow">SEARCH</div><h1>Find an episode.</h1><p>Search the published archive.</p></div><form className="big-search" onSubmit={e=>{e.preventDefault();go("/search"+(q.trim()?"?q="+encodeURIComponent(q.trim()):""))}}><Search size={20}/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Episode title, topic, description…"/><button className="btn solid" type="submit">Search</button></form>{loading?<Loading count={3}/>:<><div className="section-head"><div><div className="eyebrow">RESULTS</div><h2>{q?"For “"+q+"”":"All published episodes"}</h2></div></div><Grid items={items}/></>}</main></Shell>}

function setMeta(name,content){let m=document.head.querySelector('meta[name="'+name+'"]');if(!m){m=document.createElement("meta");m.name=name;document.head.appendChild(m)}m.content=content}
function setPropertyMeta(property,content){let m=document.head.querySelector('meta[property="'+property+'"]');if(!m){m=document.createElement("meta");m.setAttribute("property",property);document.head.appendChild(m)}m.content=content}
function setPageMeta(title,description){document.title=title;setMeta("description",description);setPropertyMeta("og:title",title);setPropertyMeta("og:description",description);setPropertyMeta("og:url",window.location.href);setPropertyMeta("og:type","website");setPropertyMeta("og:image",window.location.origin+BASE+"/icon.svg");setMeta("twitter:card","summary");setMeta("twitter:title",title);setMeta("twitter:description",description)}

function useFavorites(user){const[ids,setIds]=useState(new Set());const[loading,setLoading]=useState(false);useEffect(()=>{let active=true;if(!user){setIds(new Set());return}setLoading(true);(async()=>{const r=await SUPA.from("favorites").select("episode_id").eq("user_id",user.id);if(active){setIds(new Set((r.data||[]).map(x=>x.episode_id)));setLoading(false)}})();return()=>{active=false}},[user]);const toggle=async episodeId=>{if(!user)return {ok:false,reason:"auth"};setLoading(true);try{if(ids.has(episodeId)){const r=await SUPA.from("favorites").delete().eq("user_id",user.id).eq("episode_id",episodeId);if(r.error)throw r.error;setIds(prev=>{const n=new Set(prev);n.delete(episodeId);return n})}else{const r=await SUPA.from("favorites").insert({user_id:user.id,episode_id:episodeId});if(r.error&&r.error.code!=="23505")throw r.error;setIds(prev=>new Set(prev).add(episodeId))}return {ok:true}}catch(err){return {ok:false,error:err?.message||"Could not update favorite."}}finally{setLoading(false)}};return {ids,loading,toggle}}

function saveWatchProgress(userId,episodeId,seconds,duration){if(!userId||!episodeId||!Number.isFinite(seconds)||!Number.isFinite(duration)||duration<=0)return;try{const key="latent-watch-progress:"+userId;const data=JSON.parse(localStorage.getItem(key)||"{}");if(seconds>=duration-15){delete data[episodeId]}else{data[episodeId]={seconds,duration,percent:Math.max(0,Math.min(100,seconds/duration*100)),updatedAt:Date.now()}}localStorage.setItem(key,JSON.stringify(data))}catch{}}
function loadPlayerJs(){return new Promise((resolve,reject)=>{if(window.playerjs?.Player)return resolve(window.playerjs);const existing=document.querySelector('script[data-playerjs]');if(existing){existing.addEventListener("load",()=>resolve(window.playerjs),{once:true});existing.addEventListener("error",reject,{once:true});return}const script=document.createElement("script");script.src="https://assets.mediadelivery.net/playerjs/player-0.1.0.min.js";script.async=true;script.dataset.playerjs="1";script.onload=()=>resolve(window.playerjs);script.onerror=reject;document.head.appendChild(script)})}

